class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            if self.rank[rootU] > self.rank[rootV]:
                self.parent[rootV] = rootU
            elif self.rank[rootU] < self.rank[rootV]:
                self.parent[rootU] = rootV
            else:
                self.parent[rootV] = rootU
                self.rank[rootU] += 1

def count_remaining_robots(N, robots):
    MOD = 998244353

    # Sort robots by their starting position
    robots.sort()

    # Create union-find structure
    uf = UnionFind(N)

    # Determine which robots can activate each other
    for i in range(N):
        x, d = robots[i]
        for j in range(i + 1, N):
            if robots[j][0] >= x + d:
                break
            uf.union(i, j)

    # Count the size of each connected component
    component_sizes = {}
    for i in range(N):
        root = uf.find(i)
        if root not in component_sizes:
            component_sizes[root] = 0
        component_sizes[root] += 1

    # Calculate the number of possible sets of robots remaining
    result = 1
    for size in component_sizes.values():
        result = (result * (1 << size)) % MOD

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    robots = []
    index = 1
    for i in range(N):
        x = int(data[index])
        d = int(data[index + 1])
        robots.append((x, d))
        index += 2

    result = count_remaining_robots(N, robots)
    print(result)

